# find all cycles lengths
from itertools import combinations
# check girth via BFS
def girth(G):
    g = float('inf')
    for v in G:
        # BFS
        dist = {v:0}
        parent = {v:None}
        q = [v]
        while q:
            nq = []
            for u in q:
                for w in G[u]:
                    if w not in dist:
                        dist[w]=dist[u]+1
                        parent[w]=u
                        nq.append(w)
                    elif parent[u]!=w:
                        g = min(g, dist[u]+dist[w]+1)
            q=nq
    return g
print("girth:", girth(G))
